mapper.select:
select f.follow_id, f.partner_id, f.follower_id, f.follow_type, f.content,
       f.next_follow_date, f.next_follow_content, f.status, f.follow_time,
       f.created_at, f.create_by, f.create_time, f.remark,
       p.partner_name as partner_name
from sys_business_follow f
left join sys_partner p on f.partner_id = p.partner_id

    AND f.partner_id = #{partnerId}
    AND f.status = #{status}
    AND f.follow_type = #{followType}

order by f.follow_time desc

mapper.insert:
insert into sys_business_follow (
    partner_id, follower_id, follow_type, content, next_follow_date,
    next_follow_content, status, follow_time, create_by, create_time, remark
) values (
    #{partnerId}, #{followerId}, #{followType}, #{content}, #{nextFollowDate},
    #{nextFollowContent}, #{status}, #{followTime}, #{createBy}, #{createTime}, #{remark}
)
